mapper.select:
SELECT f.ID,f.system_code,f.system_name,f.system_desc FROM system_docking.api_task_ins a LEFT JOIN system_docking.api_task_thread_ins b on a.id=b.task_id and b.is_enable='1' LEFT JOIN system_docking.api_task_thread_index c on b.id=c.thread_id LEFT JOIN system_docking.api_platform_index_info d on c.index_id=d.id and d.is_enable='1' LEFT JOIN system_docking.api_interface_system_platform_info e on d.platform_id=e.id and e.is_enable='1' LEFT JOIN system_docking.api_interface_system_info f on e.system_id=f.id and f.is_enable='1' WHERE a.is_enable='1' AND (f.id IS NOT NULL OR f.id <> '' )
AND a.id=#{processId}
GROUP BY f.id

SELECT a.id AS process_id, a.task_code, a.task_name, b.ID AS thread_id, b.task_thread_desc, f.ID AS system_id, f.system_code, f.system_desc, d.platform_id, e.platfrom_code, h.ID AS api_id, c.index_id, h.api_contract, h.api_type AS httpMethod, h.api_method, h.api_wildcard, h.api_index_code, h.api_resource_code, h.api_time_start, h.api_time_end, h.api_time_unit, k.resource_id, l.ip_address AS resource_ip, GROUP_CONCAT( DISTINCT CONCAT( '"', i.api_head_code, '":"', i.api_head_content, '"' ) ) AS headers, GROUP_CONCAT( DISTINCT CONCAT( '"', j.api_params_code, CASE WHEN j.api_params_value_type = '4' THEN CONCAT( '":', j.api_params_value ) ELSE CONCAT( '":"', j.api_params_value, '"' ) END ) ) AS paramaters FROM system_docking.api_task_ins a LEFT JOIN system_docking.api_task_thread_ins b ON a.id = b.task_id LEFT JOIN system_docking.api_task_thread_index c ON b.id = c.thread_id LEFT JOIN system_docking.api_platform_index_info d ON c.index_id = d.id LEFT JOIN system_docking.api_interface_system_platform_info e ON d.platform_id = e.id LEFT JOIN system_docking.api_interface_system_info f ON e.system_id = f.id LEFT JOIN system_docking.api_system_api_index o ON d.id = o.index_id LEFT JOIN system_docking.api_system_api_info h ON o.api_id = h.id LEFT JOIN system_docking.api_system_api_head_info i ON h.ID = i.api_id AND i.api_head_type = '1' LEFT JOIN system_docking.api_system_api_params j ON h.ID = j.api_id LEFT JOIN system_docking.api_system_api_resource k ON h.ID = k.api_id LEFT JOIN system_docking.api_system_resource_ip l ON k.resource_id = l.resource_id LEFT JOIN system_docking.api_system_resource m ON m.ID = k.resource_id AND m.is_enable = '1' WHERE a.is_enable = '1' AND b.is_enable = '1' AND d.is_enable = '1' AND e.is_enable = '1' AND f.is_enable = '1' AND h.is_enable = '1' AND ( h.ID IS NOT NULL OR h.ID <> '' )
AND a.id=#{processId}
GROUP BY h.ID ORDER BY h.ID

SELECT a.id AS process_id, a.task_code, a.task_name, b.ID AS thread_id, b.task_thread_desc, f.ID AS system_id, f.system_code, f.system_desc, d.platform_id, e.platfrom_code, h.ID AS api_id, c.index_id, h.api_contract, h.api_type AS httpMethod, h.api_method, h.api_wildcard, h.api_index_code, h.api_time_start, h.api_time_end, h.api_time_unit, GROUP_CONCAT( DISTINCT CONCAT( '"', i.api_head_code, '":"', i.api_head_content, '"' ) ) AS headers, '' AS paramaters FROM system_docking.api_task_ins a LEFT JOIN system_docking.api_task_thread_ins b ON a.id = b.task_id LEFT JOIN system_docking.api_task_thread_index c ON b.id = c.thread_id LEFT JOIN system_docking.api_platform_index_info d ON c.index_id = d.id LEFT JOIN system_docking.api_interface_system_platform_info e ON d.platform_id = e.id LEFT JOIN system_docking.api_interface_system_info f ON e.system_id = f.id LEFT JOIN system_docking.api_system_api_index o ON d.id = o.index_id LEFT JOIN system_docking.api_system_api_info h ON o.api_id = h.id LEFT JOIN system_docking.api_system_api_head_info i ON h.ID = i.api_id AND i.api_head_type = '1' WHERE a.is_enable = '1' AND b.is_enable = '1' AND d.is_enable = '1' AND e.is_enable = '1' AND f.is_enable = '1' AND h.is_enable = '1' AND ( h.ID IS NOT NULL OR h.ID <> '' )
AND a.id=#{processId}
GROUP BY h.ID ORDER BY h.ID
